INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Kostenbewertung eines Notebooks entscheidend?', 2, '[{"text": "Preis-Leistungs-Verhältnis", "correct": true, "because": "Bietet die beste Balance"}, {"text": "Nur der Anschaffungspreis", "correct": false, "because": "Betriebskosten werden ignoriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es sinnvoll, bei der Kostenbewertung nur die günstigste Hardware zu wählen?', 1, '[{"text": "Nein", "correct": true, "because": "Leistung und Zuverlässigkeit könnten leiden"}, {"text": "Ja", "correct": false, "because": "Kosten allein sind kein gutes Kriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenfaktoren solltest du bei der Bewertung eines Systems berücksichtigen?', 5, '[{"text": "Anschaffungskosten", "correct": true, "because": "Grundlegender Kostenpunkt"}, {"text": "Stromverbrauch", "correct": true, "because": "Langfristige Betriebskosten"}, {"text": "Farbe der Komponenten", "correct": "false", "because": "Irrelevant für Kosten"}, {"text": "Wartungsaufwand", "correct": true, "because": "Beeinflusst die Gesamtkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen zur Kostenbewertung clever? a) Höhere Anschaffungskosten bedeuten bessere Qualität. b) Günstige Hardware spart immer Geld.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Kosten spiegeln nicht immer Qualität"}, {"text": "Beides stimmt", "correct": false, "because": "Günstig kann teuer werden"}, {"text": "Nur b) stimmt", "correct": false, "because": "Langfristige Kosten zählen"}, {"text": "Beides falsch", "correct": true, "because": "Beide Aussagen sind zu pauschal"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Kostenbewertung eines Servers am wichtigsten?', 2, '[{"text": "Betriebskosten wie Stromverbrauch", "correct": true, "because": "Langfristig entscheidend"}, {"text": "Nur der Kaufpreis", "correct": false, "because": "Ignoriert laufende Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine teure SSD immer die beste Wahl für ein System?', 1, '[{"text": "Nein", "correct": true, "because": "Anforderungen bestimmen die Wahl"}, {"text": "Ja", "correct": false, "because": "Teuer heißt nicht immer besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren solltest du bei der Kostenbewertung einer CPU berücksichtigen?', 5, '[{"text": "Leistung pro Euro", "correct": true, "because": "Wichtiges Preis-Leistungs-Kriterium"}, {"text": "Verpackungsdesign", "correct": false, "because": "Irrelevant für Kosten"}, {"text": "Stromverbrauch", "correct": true, "because": "Beeinflusst Betriebskosten"}, {"text": "Garantiedauer", "correct": true, "because": "Mindert Reparaturkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen zur Kostenbewertung richtig? a) Günstige Hardware hat immer höhere Folgekosten. b) Teure Hardware ist wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Nicht immer der Fall"}, {"text": "Beides stimmt", "correct": false, "because": "Teuer garantiert keine Wartungsfreiheit"}, {"text": "Nur b) stimmt", "correct": false, "because": "Wartung hängt nicht vom Preis ab"}, {"text": "Beides falsch", "correct": true, "because": "Beides ist zu verallgemeinernd"}]'),
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Kostenbewertung eines Servers am kritischsten?', 2, '[{"text": "Betriebskosten wie Stromverbrauch", "correct": true, "because": "Laufende Kosten übersteigen oft den Anschaffungspreis"}, {"text": "Nur der Kaufpreis", "correct": false, "because": "Ignoriert langfristige Ausgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es kosteneffizient, immer die neueste Hardware zu kaufen?', 1, '[{"text": "Nein", "correct": true, "because": "Ältere Modelle können günstiger und ausreichend sein"}, {"text": "Ja", "correct": false, "because": "Neuste Technik ist oft überteuert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren solltest du bei der Kostenbewertung eines Arbeitsspeichers berücksichtigen?', 5, '[{"text": "Preis pro GB", "correct": true, "because": "Misst Effizienz der Kapazität"}, {"text": "Leistungssteigerung", "correct": true, "because": "Höhere Taktfrequenz rechtfertigt Kosten"}, {"text": "Verpackungsdesign", "correct": false, "because": "Kein Einfluss auf Funktion"}, {"text": "Kompatibilität", "correct": true, "because": "Falscher RAM ist nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen zur Kostenbewertung sinnvoll? a) Teure Hardware ist langlebiger. b) Günstige Komponenten haben höhere Folgekosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Langlebigkeit hängt nicht nur vom Preis ab"}, {"text": "Nur b) stimmt", "correct": true, "because": "Günstige Teile können öfter ausfallen"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist nicht immer wahr"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist oft richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Kostenbewertung eines Laptops ignorieren?', 2, '[{"text": "Gewicht des Geräts", "correct": true, "because": "Kein direkter Kostenfaktor"}, {"text": "Energieeffizienz", "correct": false, "because": "Beeinflusst Betriebskosten"}, {"text": "Reparaturmöglichkeiten", "correct": false, "because": "Wichtig für Folgekosten"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Kostenbewertung einer SSD entscheidend?', 2, '[{"text": "Preis pro GB", "correct": true, "because": "Gibt die Kosten effizient wieder"}, {"text": "Nur die Marke", "correct": false, "because": "Marke allein sagt wenig aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es kosteneffizient, immer die teuerste CPU zu kaufen?', 1, '[{"text": "Nein", "correct": true, "because": "Leistung muss zum Bedarf passen"}, {"text": "Ja", "correct": false, "because": "Teuer heißt nicht immer besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren solltest du bei der Kostenbewertung eines Monitors berücksichtigen?', 5, '[{"text": "Auflösung", "correct": true, "because": "Beeinflusst Preis und Nutzen"}, {"text": "Reaktionszeit", "correct": true, "because": "Wichtig für spezielle Anwendungen"}, {"text": "Verpackungsdesign", "correct": false, "because": "Irrelevant für Kosten"}, {"text": "Stromverbrauch", "correct": true, "because": "Langfristige Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen zur Kostenbewertung richtig? a) Günstige Hardware hat immer höhere Folgekosten. b) Teure Hardware ist immer langlebiger.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Nicht immer zutreffend"}, {"text": "Beides stimmt", "correct": false, "because": "Beides ist nicht generell wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "Teuer garantiert keine Langlebigkeit"}, {"text": "Beides falsch", "correct": true, "because": "Beides ist zu pauschal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Kostenbewertung eines Netzteils ignorieren?', 2, '[{"text": "Wirkungsgrad", "correct": false, "because": "Beeinflusst Stromkosten"}, {"text": "Kabeldesign", "correct": true, "because": "Hat keinen Einfluss auf Kosten"}, {"text": "Leistung in Watt", "correct": false, "because": "Wichtig für Preis und Nutzen"}]');
